               ("Nilínis ni Marta ang kanilàng báhay.", "Their house is being cleaned by Marta.",
                [("Nilínis", "cleaned", "pred"), ("ni", "by", "marker"), ("Marta", "Marta", "noun"), ("ang", "the", "marker"), ("kanilàng", "their", "poss"), ("báhay", "house", "noun")]),
               ("Lúlutuin ng katúlong ang gúlay.", "The vegetables will be cooked by the helper.",
                [("Lúlutuin", "will be cooked", "pred"), ("ng", "by", "marker"), ("katúlong", "the helper", "noun"), ("ang", "the", "marker"), ("gúlay", "vegetables", "noun")]),
