               ("Áalisin niya ang kanyang sapátos.", "His/Her shoes will be removed by him/her.",
                [("Áalisin", "will be removed", "pred"), ("niya", "by him/her", "poss"), ("ang", "the", "marker"), ("kanyang", "his/her", "poss"), ("sapátos", "shoes", "noun")]),
               ("Dinádala namin ang aklát ng Tagalog sa páaralán.", "The Tagalog book is brought by us to school.",
                [("Dinádala", "is brought", "pred"), ("namin", "by us", "poss"), ("ang", "the", "marker"), ("aklát", "book", "noun"), ("ng", "of", "marker"), ("Tagalog", "Tagalog", "noun"), ("sa", "to", "marker"), ("páaralán", "school", "noun")]),
